// app.js — Homepage playground. Model ABIs, sources and defaults come from
// models/manifest.json (generated by scripts/build-models.mjs); this file only adds
// presentation: which inputs get sliders, their ranges, and output labels.
import { AvenWasmEngine } from "./wasm_engine.js";
import { highlightLine } from "./site.js";

const UI = {
  quadcopter: {
    label: "Quadcopter",
    sliders: {
      motor_rpm: { label: "Motor speed", unit: "rpm", min: 3000, max: 9000, step: 100 },
      prop_diameter_m: { label: "Propeller diameter", unit: "m", min: 0.2, max: 0.5, step: 0.005 },
      total_mass_kg: { label: "Take-off mass", unit: "kg", min: 1, max: 8, step: 0.1 },
      battery_open_circuit_volts: { label: "Battery open-circuit voltage", unit: "V", min: 11.1, max: 25.2, step: 0.1 },
      battery_internal_resistance_ohms: { label: "Battery internal resistance", unit: "Ω", min: 0.01, max: 0.1, step: 0.005 },
    },
    outputs: {
      total_thrust_n: { label: "Total thrust", unit: "N", digits: 1 },
      thrust_weight_ratio: { label: "Thrust-to-weight", unit: "×", digits: 2 },
      climb_accel_mps2: { label: "Climb acceleration", unit: "m/s²", digits: 2 },
      total_amps_draw: { label: "Current draw", unit: "A", digits: 1 },
      terminal_voltage: { label: "Terminal voltage", unit: "V", digits: 2 },
      delivered_power_w: { label: "Delivered power", unit: "W", digits: 0 },
    },
  },
  server_capacity: {
    label: "Server capacity",
    sliders: {
      reqs_per_second: { label: "Arrival rate", unit: "req/s", min: 1000, max: 150000, step: 1000 },
      avg_latency_ms: { label: "Mean latency", unit: "ms", min: 1, max: 200, step: 1 },
      target_utilization: { label: "Target utilization", unit: "", min: 0.4, max: 0.95, step: 0.01 },
      avg_payload_kb: { label: "Mean payload", unit: "KB", min: 1, max: 256, step: 1 },
    },
    outputs: {
      raw_workers: { label: "Concurrent requests", unit: "", digits: 1 },
      allocated_workers: { label: "Workers to allocate", unit: "", digits: 0 },
      total_ram_needed: { label: "RAM needed", unit: "MB", digits: 0 },
      payload_gbps: { label: "Payload bandwidth", unit: "Gbps", digits: 3 },
      wire_rate_gbps: { label: "Wire rate", unit: "Gbps", digits: 3 },
    },
  },
  portfolio: {
    label: "Portfolio",
    sliders: {
      equity_weight: { label: "Equity weight", unit: "", min: 0, max: 1, step: 0.01 },
      bond_weight: { label: "Bond weight", unit: "", min: 0, max: 1, step: 0.01 },
      reit_weight: { label: "Real-estate weight", unit: "", min: 0, max: 1, step: 0.01 },
      equity_return_pct: { label: "Equity expected return", unit: "%", min: 0, max: 20, step: 0.1 },
      equity_vol_pct: { label: "Equity volatility", unit: "%", min: 5, max: 40, step: 0.5 },
      risk_free_rate_pct: { label: "Risk-free rate", unit: "%", min: 0, max: 8, step: 0.1 },
    },
    outputs: {
      total_weight: { label: "Total weight (should be 1)", unit: "", digits: 2 },
      expected_return_pct: { label: "Expected return", unit: "%", digits: 2 },
      portfolio_vol_pct: { label: "Volatility", unit: "%", digits: 2 },
      sharpe_ratio: { label: "Sharpe ratio", unit: "", digits: 3 },
      equity_value: { label: "Equity value", unit: "$", digits: 0 },
      bond_value: { label: "Bond value", unit: "$", digits: 0 },
    },
  },
};

const REPO = "https://github.com/Thrainkrilleve/aven/blob/main/";
const engine = new AvenWasmEngine();
const $ = (id) => document.getElementById(id);

let models = [];
let current = null;
let values = {};

const decimalsOf = (step) => (String(step).split(".")[1] || "").length;
const formatNumber = (v, digits) =>
  Number.isFinite(v) ? v.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits }) : String(v);

function renderTabs() {
  const tabs = $("pg-models");
  tabs.innerHTML = "";
  for (const model of models) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pg-model";
    btn.setAttribute("role", "tab");
    btn.dataset.key = model.key;
    btn.textContent = UI[model.key]?.label ?? model.title;
    btn.addEventListener("click", () => activate(model.key));
    tabs.appendChild(btn);
  }
}

function renderSource(model) {
  $("pg-block").textContent = `forward ${model.block}`;
  const link = $("pg-source-link");
  link.href = REPO + model.example;
  link.textContent = model.example.replace("examples/", "");
  $("pg-code").innerHTML = model.source
    .split("\n")
    .map((line) => `<span data-line>${highlightLine(line)}</span>`)
    .join("\n");
}

function highlightUses(name) {
  const re = new RegExp(`\\b${name}\\b`);
  document.querySelectorAll("#pg-code [data-line]").forEach((el) => {
    el.classList.toggle("hot", Boolean(name) && re.test(el.textContent));
  });
}

function setFill(input) {
  const pct = ((input.value - input.min) / (input.max - input.min)) * 100;
  input.style.setProperty("--fill", `${pct}%`);
}

function renderSliders(model) {
  const ui = UI[model.key];
  const box = $("pg-sliders");
  box.innerHTML = "";
  for (const [name, s] of Object.entries(ui.sliders)) {
    const id = `in-${name}`;
    const row = document.createElement("div");
    row.className = "slider-row";
    row.innerHTML = `
      <label for="${id}">
        <span>${s.label}<code>${name}</code></span>
        <output for="${id}"></output>
      </label>
      <input type="range" id="${id}" min="${s.min}" max="${s.max}" step="${s.step}">`;
    const input = row.querySelector("input");
    const out = row.querySelector("output");
    const show = () => {
      out.textContent = `${formatNumber(values[name], decimalsOf(s.step))}${s.unit ? " " + s.unit : ""}`;
      setFill(input);
    };
    input.value = values[name];
    show();
    input.addEventListener("input", () => {
      values[name] = Number(input.value);
      show();
      solve();
    });
    input.addEventListener("focus", () => highlightUses(name));
    input.addEventListener("pointerdown", () => highlightUses(name));
    input.addEventListener("blur", () => highlightUses(null));
    box.appendChild(row);
  }
}

function solve() {
  const model = current;
  const ui = UI[model.key];
  const result = engine.solve(model, values);
  const finite = Object.values(result).every(Number.isFinite);

  const status = $("pg-status");
  status.className = finite ? "status-ok" : "status-ok status-bad";
  status.textContent = finite ? "Settled" : "Non-finite result (check inputs)";
  $("pg-timing").textContent = `${engine.timeSolve(model).toFixed(2)} µs / solve`;
  $("pg-timing").title = "Mean of 2,000 aven_solve calls in this browser";

  const grid = $("pg-outputs");
  grid.innerHTML = "";
  for (const [name, o] of Object.entries(ui.outputs)) {
    const cell = document.createElement("div");
    cell.className = "output";
    cell.title = name;
    cell.innerHTML = `<div class="output-name"></div><div class="output-val"></div>`;
    cell.querySelector(".output-name").textContent = o.label;
    const val = cell.querySelector(".output-val");
    val.textContent = formatNumber(result[name], o.digits);
    if (o.unit) val.insertAdjacentHTML("beforeend", `<small>${o.unit}</small>`);
    grid.appendChild(cell);
  }
}

function defaultsFor(model) {
  return Object.fromEntries(model.inputs.map((i) => [i.name, i.default]));
}

async function activate(key, overrides = {}) {
  current = models.find((m) => m.key === key) ?? models[0];
  values = defaultsFor(current);
  for (const [name, v] of Object.entries(overrides)) {
    if (name in values && Number.isFinite(v)) values[name] = v;
  }
  document.querySelectorAll(".pg-model").forEach((b) => b.setAttribute("aria-selected", String(b.dataset.key === current.key)));
  renderSource(current);
  renderSliders(current);
  try {
    await engine.load(current);
    solve();
  } catch (err) {
    $("pg-status").className = "status-ok status-bad";
    $("pg-status").textContent = "Could not load the WebAssembly model";
    console.error(err);
  }
}

function setupShare() {
  const btn = $("pg-share");
  btn.addEventListener("click", async () => {
    const url = new URL(location.origin + location.pathname);
    url.searchParams.set("model", current.key);
    const defaults = defaultsFor(current);
    for (const name of Object.keys(UI[current.key].sliders)) {
      if (values[name] !== defaults[name]) url.searchParams.set(name, values[name]);
    }
    url.hash = "playground";
    const label = btn.querySelector("span");
    try {
      await navigator.clipboard.writeText(url.toString());
      label.textContent = "Link copied";
    } catch {
      history.replaceState(null, "", url);
      label.textContent = "Link in address bar";
    }
    setTimeout(() => (label.textContent = "Copy link"), 2000);
  });
  $("pg-reset").addEventListener("click", () => activate(current.key));
}

// Older share links (/p/:id → /?model=<id>) name a row in the D1 shared_models table;
// its category is the playground model it was shared from.
async function resolveModelKey(requested) {
  if (!requested || models.some((m) => m.key === requested)) return requested;
  try {
    const res = await fetch(`/api/v1/models/${encodeURIComponent(requested)}`);
    if (res.ok) return (await res.json()).category;
  } catch {}
  return null;
}

async function init() {
  if (!$("pg-models")) return;
  try {
    const res = await fetch("/models/manifest.json");
    models = (await res.json()).models.filter((m) => UI[m.key]);
  } catch (err) {
    $("pg-status").className = "status-ok status-bad";
    $("pg-status").textContent = "Could not load the model manifest";
    return;
  }
  renderTabs();
  setupShare();

  const params = new URLSearchParams(location.search);
  const key = await resolveModelKey(params.get("model"));
  const overrides = {};
  for (const [k, v] of params) if (k !== "model") overrides[k] = Number(v);
  await activate(key ?? models[0].key, overrides);
}

init();
